(async () => {
  assert.equal(resolveOptions({ timeoutMs: 0 }).timeoutMs, 10000);
  const originalSetTimeout = global.setTimeout;
  const scheduled = [];
  global.setTimeout = (fn, ms, ...args) => { scheduled.push(ms); return originalSetTimeout(fn, ms, ...args); };
  try {
    await downloadExport(async () => ({ ok: true, status: 200, text: async () => '' }), 'https://x.test', '2026-11-08');
  } finally { global.setTimeout = originalSetTimeout; }
  console.log('Export with timeoutMs:0 scheduled timers:', scheduled);

  let mutations = 0;
  await request(async (url, init) => {
    assert.equal(init.method, 'POST');
    mutations++;
    return { status: mutations === 1 ? 503 : 200 };
  }, 'https://x.test/charge', { init: { method: 'POST', body: 'amount=100' }, baseDelayMs: 0 });
  assert.equal(mutations, 2);
  console.log('Non-idempotent POST executions after one 503:', mutations);

  let canceled = false;
  const failed = new Response(new ReadableStream({ cancel() { canceled = true; } }), { status: 503 });
  let calls = 0;
  await request(async () => ++calls === 1 ? failed : new Response('ok'), 'https://x.test', { baseDelayMs: 0 });
  assert.equal(failed.bodyUsed, false);
  assert.equal(canceled, false);
  console.log('Discarded error body: bodyUsed =', failed.bodyUsed, '; canceled =', canceled);

  let retries = 0;
  const started = performance.now();
  await request(async () => ++retries === 1 ? new Response('', { status: 429, headers: { 'Retry-After': '60' } }) : new Response('ok'), 'https://x.test', { baseDelayMs: 0 });
  console.log('Retry-After:60; retry completed in', Math.round(performance.now() - started), 'ms');
})().catch(err => { console.error(err); process.exitCode = 1; });
